-- Load production.FactFacilityProcessing (fact).
-- One stored procedure per destination table (DE Policy v2, 5.3).
-- Generated by `python -m fde render` from models/gold/production/FactFacilityProcessing.yml. Do not edit: change the spec and render again.

CREATE OR ALTER PROCEDURE [production].[LoadFactFacilityProcessing]
    @LoadDate date,
    @LoadStepID varchar(36)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Now datetime2(6) = SYSUTCDATETIME();
    DECLARE @MaxKey bigint = (SELECT COALESCE(MAX([FactFacilityProcessing_SK]), 0)
                              FROM [production].[FactFacilityProcessing] WHERE [FactFacilityProcessing_SK] > 0);

    MERGE [production].[FactFacilityProcessing] AS target
    USING (
        SELECT
            CAST(s.[FacilityProcessing_BK] AS int) AS [FacilityProcessing_BK],
            CAST(s.[DimFacility_SK] AS bigint) AS [DimFacility_SK],
            CAST(s.[DimDataSource_SK] AS bigint) AS [DimDataSource_SK],
            CAST(s.[FacilityType] AS varchar(30)) AS [FacilityType],
            CAST(s.[InputMaterial] AS varchar(100)) AS [InputMaterial],
            CAST(s.[OutputMaterial] AS varchar(120)) AS [OutputMaterial],
            CAST(s.[ReportingPeriod] AS varchar(30)) AS [ReportingPeriod],
            CAST(s.[HasPurchasedMaterial] AS bit) AS [HasPurchasedMaterial],
            CAST(s.[ReportingYear] AS int) AS [ReportingYear],
            CAST(s.[InputValueTonnes] AS decimal(18,4)) AS [InputValueTonnes],
            CAST(s.[OutputValueTonnes] AS decimal(18,4)) AS [OutputValueTonnes],
            CAST(s.[GradePartsPerMillion] AS decimal(18,4)) AS [GradePartsPerMillion],
            CAST(s.[RecoveryRate] AS decimal(18,8)) AS [RecoveryRate],
            CAST(s.[AmountSoldTonnes] AS decimal(18,4)) AS [AmountSoldTonnes],
            CAST(s.[MetalPayableTonnes] AS decimal(18,4)) AS [MetalPayableTonnes],
            @MaxKey + ROW_NUMBER() OVER (ORDER BY s.[FacilityProcessing_BK]) AS [NewKey]
        FROM [stage].[FactFacilityProcessingSource] AS s
    ) AS source
    ON target.[FacilityProcessing_BK] = source.[FacilityProcessing_BK]
    WHEN MATCHED AND (
        (target.[DimFacility_SK] <> source.[DimFacility_SK] OR (target.[DimFacility_SK] IS NULL AND source.[DimFacility_SK] IS NOT NULL) OR (target.[DimFacility_SK] IS NOT NULL AND source.[DimFacility_SK] IS NULL))
        OR (target.[DimDataSource_SK] <> source.[DimDataSource_SK] OR (target.[DimDataSource_SK] IS NULL AND source.[DimDataSource_SK] IS NOT NULL) OR (target.[DimDataSource_SK] IS NOT NULL AND source.[DimDataSource_SK] IS NULL))
        OR (target.[FacilityType] <> source.[FacilityType] OR (target.[FacilityType] IS NULL AND source.[FacilityType] IS NOT NULL) OR (target.[FacilityType] IS NOT NULL AND source.[FacilityType] IS NULL))
        OR (target.[InputMaterial] <> source.[InputMaterial] OR (target.[InputMaterial] IS NULL AND source.[InputMaterial] IS NOT NULL) OR (target.[InputMaterial] IS NOT NULL AND source.[InputMaterial] IS NULL))
        OR (target.[OutputMaterial] <> source.[OutputMaterial] OR (target.[OutputMaterial] IS NULL AND source.[OutputMaterial] IS NOT NULL) OR (target.[OutputMaterial] IS NOT NULL AND source.[OutputMaterial] IS NULL))
        OR (target.[ReportingPeriod] <> source.[ReportingPeriod] OR (target.[ReportingPeriod] IS NULL AND source.[ReportingPeriod] IS NOT NULL) OR (target.[ReportingPeriod] IS NOT NULL AND source.[ReportingPeriod] IS NULL))
        OR (target.[HasPurchasedMaterial] <> source.[HasPurchasedMaterial] OR (target.[HasPurchasedMaterial] IS NULL AND source.[HasPurchasedMaterial] IS NOT NULL) OR (target.[HasPurchasedMaterial] IS NOT NULL AND source.[HasPurchasedMaterial] IS NULL))
        OR (target.[ReportingYear] <> source.[ReportingYear] OR (target.[ReportingYear] IS NULL AND source.[ReportingYear] IS NOT NULL) OR (target.[ReportingYear] IS NOT NULL AND source.[ReportingYear] IS NULL))
        OR (target.[InputValueTonnes] <> source.[InputValueTonnes] OR (target.[InputValueTonnes] IS NULL AND source.[InputValueTonnes] IS NOT NULL) OR (target.[InputValueTonnes] IS NOT NULL AND source.[InputValueTonnes] IS NULL))
        OR (target.[OutputValueTonnes] <> source.[OutputValueTonnes] OR (target.[OutputValueTonnes] IS NULL AND source.[OutputValueTonnes] IS NOT NULL) OR (target.[OutputValueTonnes] IS NOT NULL AND source.[OutputValueTonnes] IS NULL))
        OR (target.[GradePartsPerMillion] <> source.[GradePartsPerMillion] OR (target.[GradePartsPerMillion] IS NULL AND source.[GradePartsPerMillion] IS NOT NULL) OR (target.[GradePartsPerMillion] IS NOT NULL AND source.[GradePartsPerMillion] IS NULL))
        OR (target.[RecoveryRate] <> source.[RecoveryRate] OR (target.[RecoveryRate] IS NULL AND source.[RecoveryRate] IS NOT NULL) OR (target.[RecoveryRate] IS NOT NULL AND source.[RecoveryRate] IS NULL))
        OR (target.[AmountSoldTonnes] <> source.[AmountSoldTonnes] OR (target.[AmountSoldTonnes] IS NULL AND source.[AmountSoldTonnes] IS NOT NULL) OR (target.[AmountSoldTonnes] IS NOT NULL AND source.[AmountSoldTonnes] IS NULL))
        OR (target.[MetalPayableTonnes] <> source.[MetalPayableTonnes] OR (target.[MetalPayableTonnes] IS NULL AND source.[MetalPayableTonnes] IS NOT NULL) OR (target.[MetalPayableTonnes] IS NOT NULL AND source.[MetalPayableTonnes] IS NULL))
    ) THEN UPDATE SET
        [DimFacility_SK] = source.[DimFacility_SK],
        [DimDataSource_SK] = source.[DimDataSource_SK],
        [FacilityType] = source.[FacilityType],
        [InputMaterial] = source.[InputMaterial],
        [OutputMaterial] = source.[OutputMaterial],
        [ReportingPeriod] = source.[ReportingPeriod],
        [HasPurchasedMaterial] = source.[HasPurchasedMaterial],
        [ReportingYear] = source.[ReportingYear],
        [InputValueTonnes] = source.[InputValueTonnes],
        [OutputValueTonnes] = source.[OutputValueTonnes],
        [GradePartsPerMillion] = source.[GradePartsPerMillion],
        [RecoveryRate] = source.[RecoveryRate],
        [AmountSoldTonnes] = source.[AmountSoldTonnes],
        [MetalPayableTonnes] = source.[MetalPayableTonnes],
        [LastUpdateLoadStepID] = @LoadStepID,
        [LastUpdateTimestamp] = @Now
    WHEN NOT MATCHED BY TARGET THEN INSERT (
        [FactFacilityProcessing_SK],
        [FacilityProcessing_BK],
        [DimFacility_SK],
        [DimDataSource_SK],
        [FacilityType],
        [InputMaterial],
        [OutputMaterial],
        [ReportingPeriod],
        [HasPurchasedMaterial],
        [ReportingYear],
        [InputValueTonnes],
        [OutputValueTonnes],
        [GradePartsPerMillion],
        [RecoveryRate],
        [AmountSoldTonnes],
        [MetalPayableTonnes],
        [InsertLoadStepID],
        [InsertTimestamp],
        [LastUpdateLoadStepID],
        [LastUpdateTimestamp]
    ) VALUES (
        source.[NewKey],
        source.[FacilityProcessing_BK],
        source.[DimFacility_SK],
        source.[DimDataSource_SK],
        source.[FacilityType],
        source.[InputMaterial],
        source.[OutputMaterial],
        source.[ReportingPeriod],
        source.[HasPurchasedMaterial],
        source.[ReportingYear],
        source.[InputValueTonnes],
        source.[OutputValueTonnes],
        source.[GradePartsPerMillion],
        source.[RecoveryRate],
        source.[AmountSoldTonnes],
        source.[MetalPayableTonnes],
        @LoadStepID,
        @Now,
        @LoadStepID,
        @Now
    );
END
GO
